        ]
      },
      "action": {
        "label": "打开天气"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "runIcon",
      "src": "resources/base/media/icon_run.png",
      "use": "fitness glyph",
      "description": "跑步图标素材，用于替代用户请求中的运动小图标视觉，适合作为运动指数主视觉。",
      "bindTo": "/assets/runIcon"
    }
  ]
}

